/**
 * Get book value for a symbol
 */
export function getStaticBookValue(symbol: string): number | null {
    const data = STATIC_BOOK_VALUES[symbol.toUpperCase()];
    return data?.bookValue ?? null;
}

/**
 * Get all fundamentals for a symbol
 */
export function getStaticFundamentals(symbol: string): StaticFundamentals | null {
    return STATIC_BOOK_VALUES[symbol.toUpperCase()] ?? null;
}

/**
 * Get all available symbols
 */
export function getAllStaticSymbols(): string[] {
    return Object.keys(STATIC_BOOK_VALUES);
}

